			return nil, fmt.Errorf("unknown host %s", host)
		})
		implCluster.ClientRoutesHandlerData(opaqueStorageValuexxxxxx).InternalRouteCache = newCache(map[string]clientRouteCacheEntry{
			"h1": newCacheEntryWithCurrent(
