	if err != nil {
		t.Fatal(err)
	}
	reader := NewRowReader(columns, chain, lease)
	row, err := plan.Decode(reader)
	if err != nil {
		t.Fatal(err)
	}
	if err := FinishRowReader(reader); err != nil {
		t.Fatal(err)
	}
	if err := reader.cursor.RequireEnd(); err != nil {
