	if _, err := row.Body.At(0); !errors.Is(err, cqltype.ErrReleased) {
		t.Fatalf("expired row: %v", err)
	}
	payload[0] = 'X'
	if got := string(clone.Body.OwnedBytes()); got != "borrowed payload" {
		t.Fatalf("clone retained borrowed input: %q", got)
	}
}

