	typ, _ := cqltype.UDTType("ks", "record", cqltype.ColumnSpec{Name: "body", Type: text}, cqltype.ColumnSpec{Name: "extra", Type: integer}, cqltype.ColumnSpec{Name: "id", Type: integer})
