		for _, want := range []CellState{CellNull, CellPresent} {
			if e := s.Cell(false, func(state CellState, c *Stream) error {
				if state != want || c.Remaining() != 0 {
					t.Fatal("null/empty collapsed")
				}
				return nil
			}); e != nil {
				t.Fatal(e)
			}
		}
		if e := s.RequireEnd(); e != nil {
			t.Fatal(e)
		}
	}
}

