			cluster := createV2Cluster()
			v2ConfigureRouting(t, &cluster, RoutingOptions{TokenAware: true})
			if configuredKeyspace {
				cluster.Keyspace = keyspace
			}
			testIfPolicyInitializedProperly(t, cluster, keyspace)
		})
	}
}

