	found := false
	frame.Each(func(s wire.Span) error {
		if uintptr(unsafe.Pointer(unsafe.SliceData(s.Bytes()))) == ptr && int64(s.Len()) == size {
			found = true
		}
		return nil
	})
	if !found || calls != 1 || input != int64(len(data)) {
