						err = cursor.Err()
						cursor.Close()
					}
					if err == nil {
						t.Fatal("corrupt checksum accepted")
					}
					finishRead()
					cancel()
					b.Close()
					peer.Close()
					s.Close()
					<-done
				}
			}
		})
