	if err := implCluster.InternalSessionRefreshRingNow(s); err != nil {
		t.Fatal(err)
	}
	if implCluster.SessionData(s).InternalHostSource.InternalGetHost(peer.hostID.String()) != nil {
		t.Fatal("stale gossip resurrected removed host")
