	implCluster.InternalSessionRecordV2Topology(s, &oldevents.TopologyChangeEvent{Change: "NEW_NODE", Host: peer.ip, Port: 9042})
	if err := implCluster.InternalSessionRefreshRingNow(s); err != nil {
