func TestV2PageNextIntoMixedCurrentAndRetention(t *testing.T) {
	p := step03Page(t, "one", "two", "three")
	defer p.Close()
	var first, second Bytes
	if !p.NextInto(&first) || string(first.OwnedBytes()) != "one" {
